// Express.js Backend returning precise 2xx codes

// Standard Read -> 200 OK
app.get('/api/users', (req, res) => {
  res.status(200).json([{ name: "John" }]);
});

// Creation -> 201 Created
app.post('/api/users', async (req, res) => {
  const newUser = await db.create(req.body);
  res.status(201).json(newUser);
});

// Deletion -> 204 No Content
app.delete('/api/users/1', async (req, res) => {
  await db.delete(1);
  // We use .send() instead of .json() because 204 forbids a response body!
  res.status(204).send(); 
});
